int rec(vi &c, vi &h, int cur_mon, int m, int salary, int x, int happiness, vvi &dp){
    if(cur_mon>m)   return 0;

    if(dp[cur_mon][happiness]!=-1) return dp[cur_mon][happiness];
    int op= rec(c,h,cur_mon+1, m, salary+x, x, happiness, dp);

    if(salary>=c[cur_mon]){
        op= max(op, h[cur_mon] + rec(c,h,cur_mon+1, m, salary-c[cur_mon]+x, x, happiness+h[cur_mon],dp));
    }
    return dp[cur_mon][happiness]=op;
    // return op;
} 

