#define pb push_back
int main(){
    ll t;
    cin>>t;
    while(t--){
        ll n;
        cin>>n;
        string s;
        cin>>s;
        vector<ll>u;vector<ll>d;vector<ll>e;vector<ll>w;
        vector<vector<ll>>mega;
        for(ll i=0;i<n;i++){
            if(s[i]=='N')u.pb(i);
            if(s[i]=='W')w.pb(i);
            if(s[i]=='E')e.pb(i);
            if(s[i]=='S')d.pb(i);
        }
        if((u.size()+d.size())%2==0 && (w.size()+e.size())%2==0){
            string ans=s;
            if(u.size()%2==1){
                ans[u[u.size()-1]]='R';
                ans[d[d.size()-1]]='R';
                u.pop_back();d.pop_back();
            }
            if(e.size()%2==1){
                ans[e[e.size()-1]]='H';
                ans[w[w.size()-1]]='H';
                e.pop_back();w.pop_back();
            }
            mega.push_back(u);mega.push_back(d);mega.push_back(e);mega.push_back(w);
            for(ll i=0;i<4;i++){
                for(ll j=0;j<mega[i].size();j++){//mega[i] is nothing but u,d,w,e
                    if(j>=mega[i].size()/2){
                        ans[mega[i][j]]='R';
                    }
                    else ans[mega[i][j]]='H';
                }
            }
            ll flagr=0,flagh=0;
            for(ll i=0;i<n;i++){
                if(ans[i]=='R')flagr=1;
                if(ans[i]=='H')flagh=1;
            }
            if(flagr==0||flagh==0)cout<<"NO"<<endl;
            else cout<<ans<<endl;
        }
        else{
            cout<<"NO"<<endl;
        }
    }
    return 0;
}

